macro_rules! deps {
    () => {
        Expr!();
        ExprKind!();
        Block!();
        Lit!();
        StructTailExpr!();
        LetExpr!();
        FnKind!();
        ConstBlock!();
        InlineAsm!();
        Closure!();
        Path!();
        Visitor!();
    };
}

macro_rules! walk_expr {
    () => {
        deps!();
        pub fn walk_expr < 'v , V : Visitor < 'v > > (visitor : & mut V , expression : & 'v Expr < 'v >) -> V :: Result { let Expr { hir_id , kind , span } = expression ; try_visit ! (visitor . visit_id (* hir_id)) ; match * kind { ExprKind :: Array (subexpressions) => { walk_list ! (visitor , visit_expr , subexpressions) ; } ExprKind :: ConstBlock (ref const_block) => { try_visit ! (visitor . visit_inline_const (const_block)) } ExprKind :: Repeat (ref element , ref count) => { try_visit ! (visitor . visit_expr (element)) ; try_visit ! (visitor . visit_const_arg_unambig (count)) ; } ExprKind :: Struct (ref qpath , fields , ref optional_base) => { try_visit ! (visitor . visit_qpath (qpath , * hir_id , * span)) ; walk_list ! (visitor , visit_expr_field , fields) ; match optional_base { StructTailExpr :: Base (base) => try_visit ! (visitor . visit_expr (base)) , StructTailExpr :: None | StructTailExpr :: DefaultFields (_) => { } } } ExprKind :: Tup (subexpressions) => { walk_list ! (visitor , visit_expr , subexpressions) ; } ExprKind :: Call (ref callee_expression , arguments) => { try_visit ! (visitor . visit_expr (callee_expression)) ; walk_list ! (visitor , visit_expr , arguments) ; } ExprKind :: MethodCall (ref segment , receiver , arguments , _) => { try_visit ! (visitor . visit_path_segment (segment)) ; try_visit ! (visitor . visit_expr (receiver)) ; walk_list ! (visitor , visit_expr , arguments) ; } ExprKind :: Use (expr , _) => { try_visit ! (visitor . visit_expr (expr)) ; } ExprKind :: Binary (_ , ref left_expression , ref right_expression) => { try_visit ! (visitor . visit_expr (left_expression)) ; try_visit ! (visitor . visit_expr (right_expression)) ; } ExprKind :: AddrOf (_ , _ , ref subexpression) | ExprKind :: Unary (_ , ref subexpression) => { try_visit ! (visitor . visit_expr (subexpression)) ; } ExprKind :: Cast (ref subexpression , ref typ) | ExprKind :: Type (ref subexpression , ref typ) => { try_visit ! (visitor . visit_expr (subexpression)) ; try_visit ! (visitor . visit_ty_unambig (typ)) ; } ExprKind :: DropTemps (ref subexpression) => { try_visit ! (visitor . visit_expr (subexpression)) ; } ExprKind :: Let (LetExpr { span : _ , pat , ty , init , recovered : _ }) => { try_visit ! (visitor . visit_expr (init)) ; try_visit ! (visitor . visit_pat (pat)) ; visit_opt ! (visitor , visit_ty_unambig , ty) ; } ExprKind :: If (ref cond , ref then , ref else_opt) => { try_visit ! (visitor . visit_expr (cond)) ; try_visit ! (visitor . visit_expr (then)) ; visit_opt ! (visitor , visit_expr , else_opt) ; } ExprKind :: Loop (ref block , ref opt_label , _ , _) => { visit_opt ! (visitor , visit_label , opt_label) ; try_visit ! (visitor . visit_block (block)) ; } ExprKind :: Match (ref subexpression , arms , _) => { try_visit ! (visitor . visit_expr (subexpression)) ; walk_list ! (visitor , visit_arm , arms) ; } ExprKind :: Closure (& Closure { def_id , binder : _ , bound_generic_params , fn_decl , body , capture_clause : _ , fn_decl_span : _ , fn_arg_span : _ , kind : _ , constness : _ , }) => { walk_list ! (visitor , visit_generic_param , bound_generic_params) ; try_visit ! (visitor . visit_fn (FnKind :: Closure , fn_decl , body , * span , def_id)) ; } ExprKind :: Block (ref block , ref opt_label) => { visit_opt ! (visitor , visit_label , opt_label) ; try_visit ! (visitor . visit_block (block)) ; } ExprKind :: Assign (ref lhs , ref rhs , _) => { try_visit ! (visitor . visit_expr (rhs)) ; try_visit ! (visitor . visit_expr (lhs)) ; } ExprKind :: AssignOp (_ , ref left_expression , ref right_expression) => { try_visit ! (visitor . visit_expr (right_expression)) ; try_visit ! (visitor . visit_expr (left_expression)) ; } ExprKind :: Field (ref subexpression , ident) => { try_visit ! (visitor . visit_expr (subexpression)) ; try_visit ! (visitor . visit_ident (ident)) ; } ExprKind :: Index (ref main_expression , ref index_expression , _) => { try_visit ! (visitor . visit_expr (main_expression)) ; try_visit ! (visitor . visit_expr (index_expression)) ; } ExprKind :: Path (ref qpath) => { try_visit ! (visitor . visit_qpath (qpath , * hir_id , * span)) ; } ExprKind :: Break (ref destination , ref opt_expr) => { visit_opt ! (visitor , visit_label , & destination . label) ; visit_opt ! (visitor , visit_expr , opt_expr) ; } ExprKind :: Continue (ref destination) => { visit_opt ! (visitor , visit_label , & destination . label) ; } ExprKind :: Ret (ref optional_expression) => { visit_opt ! (visitor , visit_expr , optional_expression) ; } ExprKind :: Become (ref expr) => try_visit ! (visitor . visit_expr (expr)) , ExprKind :: InlineAsm (ref asm) => { try_visit ! (visitor . visit_inline_asm (asm , * hir_id)) ; } ExprKind :: OffsetOf (ref container , ref fields) => { try_visit ! (visitor . visit_ty_unambig (container)) ; walk_list ! (visitor , visit_ident , fields . iter () . copied ()) ; } ExprKind :: Yield (ref subexpression , _) => { try_visit ! (visitor . visit_expr (subexpression)) ; } ExprKind :: UnsafeBinderCast (_kind , expr , ty) => { try_visit ! (visitor . visit_expr (expr)) ; visit_opt ! (visitor , visit_ty_unambig , ty) ; } ExprKind :: Lit (lit) => try_visit ! (visitor . visit_lit (* hir_id , lit , false)) , ExprKind :: Err (_) => { } } V :: Result :: output () }
    };
}

walk_expr!();